import{c as r,Q as o,j as a,m as e}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"ABSD-基于架构的软件设计","description":"","frontmatter":{"title":"ABSD-基于架构的软件设计"},"headers":[],"relativePath":"综合知识/架构设计/基于架构的软件设计.md","filePath":"综合知识/架构设计/基于架构的软件设计.md","lastUpdated":null}'),s={name:"综合知识/架构设计/基于架构的软件设计.md"};function d(n,t,l,i,h,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<blockquote><p>ABSD 是架构设计的核心方法论，六个子过程和三基础是高频选择题考点。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] ABSD 三个基础</li><li>[ ] ABSD 六个子过程</li><li>[ ] 架构复审目的与参与者</li><li>[ ] 架构文档化核心输出</li><li>[ ] 软件系统四大基本功能 + 三硬件构件</li><li>[ ] 视角与视图（静态/动态/配置）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、absd-概述" tabindex="-1">一、ABSD 概述 <a class="header-anchor" href="#一、absd-概述" aria-label="Permalink to &quot;一、ABSD 概述&quot;">​</a></h3><blockquote><p>ABSD 方法是由<strong>商业、质量和功能需求</strong>的组合驱动的，是一个<strong>自顶向下、递归细化</strong>的方法，直到能产生<strong>软件构件和类</strong>。</p></blockquote><p><strong>ABSD 方法的三个基础：</strong></p><ol><li>对系统进行<strong>功能分解</strong></li><li>采用<strong>架构风格</strong>实现质量属性与商业需求</li><li>采用<strong>软件模板</strong>设计软件结构</li></ol><blockquote><p>⚠️ &quot;强调由业务、质量和功能需求的组合驱动&quot; 本身<strong>不属于</strong>三个基础（而是方法驱动因素）。</p></blockquote><h3 id="二、absd-六个子过程-高频必记" tabindex="-1">二、ABSD 六个子过程（高频必记） <a class="header-anchor" href="#二、absd-六个子过程-高频必记" aria-label="Permalink to &quot;二、ABSD 六个子过程（高频必记）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>架构需求 → 架构设计 → 架构文档化 → 架构复审 → 架构实现 → 架构演化</span></span></code></pre></div><table tabindex="0"><thead><tr><th>子过程</th><th>核心内容</th></tr></thead><tbody><tr><td><strong>1. 架构需求</strong></td><td>获取需求（质量目标 + 系统商业目标 + 开发人员商业目标）</td></tr><tr><td><strong>2. 架构设计</strong></td><td>设计方案</td></tr><tr><td><strong>3. 架构文档化</strong></td><td>输出<strong>架构规格说明书</strong> + <strong>测试架构需求的质量设计说明书</strong></td></tr><tr><td><strong>4. 架构复审</strong></td><td>标识潜在风险，及早发现缺陷和错误</td></tr><tr><td><strong>5. 架构实现</strong></td><td>编码实现（基于文档化后的架构说明书）</td></tr><tr><td><strong>6. 架构演化</strong></td><td>应对需求变化，需先进行<strong>需求变化归类</strong></td></tr></tbody></table><blockquote><p>⚠️ 标识构件的正确顺序：<strong>生成类图 → 对类进行分组 → 把类打包成构件</strong></p></blockquote><h3 id="三、架构复审" tabindex="-1">三、架构复审 <a class="header-anchor" href="#三、架构复审" aria-label="Permalink to &quot;三、架构复审&quot;">​</a></h3><ul><li>目的：<strong>标识潜在风险</strong>，及早发现架构设计中的缺陷和错误</li><li>必须邀请：<strong>独立于系统开发的外部人员</strong>（领域专家）</li><li>复审过程由<strong>用户代表与领域专家</strong>决定架构是否满足需求</li></ul><h3 id="四、架构描述与需求对应" tabindex="-1">四、架构描述与需求对应 <a class="header-anchor" href="#四、架构描述与需求对应" aria-label="Permalink to &quot;四、架构描述与需求对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>描述对象</th><th>使用工具</th></tr></thead><tbody><tr><td>架构</td><td><strong>视角与视图</strong></td></tr><tr><td>功能需求</td><td><strong>用例</strong></td></tr><tr><td>质量需求</td><td><strong>质量场景</strong></td></tr></tbody></table><h3 id="五、软件系统四大基本功能-三硬件构件" tabindex="-1">五、软件系统四大基本功能 + 三硬件构件 <a class="header-anchor" href="#五、软件系统四大基本功能-三硬件构件" aria-label="Permalink to &quot;五、软件系统四大基本功能 + 三硬件构件&quot;">​</a></h3><p><strong>四大基本功能（自上而下）：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据存储</strong></td><td>存储和检索数据</td></tr><tr><td><strong>数据访问逻辑</strong></td><td>处理访问数据的过程</td></tr><tr><td><strong>应用逻辑</strong></td><td>DFD/用例/功能需求中记录的业务逻辑</td></tr><tr><td><strong>表示逻辑</strong></td><td>向用户显示信息并接收用户命令</td></tr></tbody></table><p><strong>三硬件构件：</strong> 客户端（Clients）、服务器（Servers）、网络（Network）</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>参见 <a href="./.html">架构师-备考 综合知识-架构设计-架构设计方法#练习题</a>（Q6, Q7, Q9, Q12, Q13, Q18, Q19, Q21, Q22, Q24, Q25, Q28, Q29, Q30, Q31, Q32, Q33, Q34, Q35, Q36, Q37, Q38, Q39 等）</p>',23)])])}const p=r(s,[["render",d]]);export{c as __pageData,p as default};
